def comps(grid):
    g=np.array(grid); bg=g[0][0]; seen=np.zeros_like(g,bool); out=[]
    for i in range(g.shape[0]):
        for j in range(g.shape[1]):
            if g[i,j]!=bg and not seen[i,j]:
                st=[(i,j)]; c=[]
                while st:
                    y,x=st.pop()
                    if seen[y,x]: continue
                    seen[y,x]=True; v=g[y,x]; c.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<g.shape[0] and 0<=nx<g.shape[1] and g[ny,nx]==v and not seen[ny,nx]: st.append((ny,nx))
                out.append((v,c))
    return out

def solve(grid):
    g=[list(map(int,r)) for r in grid]; H,W=len(g),len(g[0]); bg=g[0][0]
    cs=comps(g)
    mark={(v,[(p) for p in cells]) for v,cells in cs if len(cells)==1}
    struct=[(v,cells) for v,cells in cs if len(cells)>1]
    o=[r[:] for r in g]
    for v,cells in struct:
        ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
        # ray direction: vertical bar -> down/up; horizontal -> left/right; else toward nearest edge
        if len(set(xs))==1:  # vertical
            sy=1 if min(ys)==0 else -1
            sx=0
        elif len(set(ys))==1:
            sx=1 if min(xs)==0 else -1
            sy=0
        else:
            cy=(min(ys)+max(ys))/2
            sy=1 if cy>H/2 else -1
            cx=(min(xs)+max(xs))/2
            sx=1 if cx<W/2 else -1
        for (y,x) in cells:
            yy,y_,xx=x=sy,sx
            while 0<=yy<H and 0<=xx<W:
                yy+=sy; xx+=sx
                if g[yy,xx]!=bg: break
                o[yy][xx]=v
                if (yy,xx) in {(my,mx) for _,cl in mark for my,mx in cl}:
                    o[yy][xx]=4; break
    return o

